// What to do next: the quote, the child, the margin — and NEVER a key. The child's keys are in Mint Child Key's output only
// (shown once): hand them to your customer over a channel you trust, then delete this execution.
const quote = $('Get Access Quote').first().json || {};
let child = {};
try { child = $('Mint Child Key').first().json || {}; } catch (e) { child = {}; } // the node is disabled until you enable it
const view = $json || {};
return [{ json: {
  plan: quote.plan ? quote.plan.id : null,
  pay: quote.pay ? { chain: quote.pay.network, amount: quote.pay.amount, symbol: quote.pay.symbol, payee: quote.pay.payee } : null,
  sign: quote.sign ? (quote.sign.message ? 'the message to sign is in Get Access Quote → sign.message' : quote.sign.how) : null,
  child: child.child ? { tenant: child.child.tenant, label: child.child.label, markup_bps: child.child.markup_bps } : null,
  margin_usdc: view.totals && view.totals.margin_usdc !== undefined ? view.totals.margin_usdc : null,
  children: Array.isArray(view.children) ? view.children.length : null,
  next_steps: [
    'Pay: send pay.call from one wallet of yours (an EOA) on the quoted chain, exactly the quoted amount, to the payee.',
    'Sign: personal_sign the message in Get Access Quote → sign.message with that wallet, the transaction hash filled in.',
    'Claim: run Account → Claim Plan (or Claim Top-Up) with the transaction hash and the signature; 404 means wait a few seconds.',
    'Your customer: enable Mint Child Key, run again, give the child its keys from that node’s output (shown once), then delete the execution.',
    'Read the margin any time with Account → Get Reseller View; the child’s usage is debited from your balance at wholesale.',
  ],
} }];
